import os
import shutil
import glob

print("=== CWD ===")
print(os.getcwd())
print("=== Workspace files ===")
for f in sorted(os.listdir(".")):
    print(" ", f)

print("=== Skill directory contents ===")
skill_dir = ".codex/skills/pdf"
if os.path.isdir(skill_dir):
    for root, dirs, files in os.walk(skill_dir):
        for f in files:
            print(" ", os.path.join(root, f))
else:
    print("  skill dir not found at", skill_dir)

print("=== PDF-related CLI tools ===")
for tool in ["qpdf", "pdftk", "pdfunite", "gs", "pdftotext", "pdfinfo", "python3"]:
    path = shutil.which(tool)
    print(f"  {tool}: {path}")

print("=== Python sys.path ===")
import sys
for p in sys.path:
    print(" ", p)

print("=== pip list (pdf related) ===")
try:
    import subprocess
    r = subprocess.run([sys.executable, "-m", "pip", "list"], capture_output=True, text=True, timeout=60)
    for line in r.stdout.splitlines():
        low = line.lower()
        if any(k in low for k in ["pdf", "report", "fpdf", "mupdf", "pypdf", "matplotlib", "numpy", "pillow", "pil"]):
            print("  ", line)
except Exception as e:
    print("  pip list failed:", e)

import importlib
import os
import sys

print("=== Module check ===")
for mod in ["pdf2image", "PIL", "pypdf", "PyPDF2", "reportlab", "fpdf", "fitz", "numpy"]:
    try:
        m = importlib.import_module(mod)
        print(f"{mod}: OK -> {getattr(m, '__file__', 'n/a')}")
    except Exception as e:
        print(f"{mod}: missing ({type(e).__name__})")

print()
print("=== Search likely site-packages dirs for pdf libs ===")
search_dirs = []
for p in sys.path:
    if os.path.isdir(p) and ("site-packages" in p or "workspace" in p or "runtime" in p):
        search_dirs.append(p)

seen = set()
for d in search_dirs:
    if d in seen:
        continue
    seen.add(d)
    print(f"-- {d}")
    try:
        entries = sorted(os.listdir(d))
    except Exception as e:
        print("   (list failed:", e, ")")
        continue
    for name in entries:
        low = name.lower()
        if any(k in low for k in ["pdf", "pypdf", "reportlab", "fpdf", "mupdf", "fitz", "pdf2", "pikepdf"]):
            print("   ", name)

